import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function TeacherContent({ userName, teachingSubject, materials, fetchData, timetable, preSelectedGrade, setPreSelectedGrade }) {
  const [formTitle, setFormTitle] = useState('');
  const [formType, setFormType] = useState('PDF'); 
  const [formFilePath, setFormFilePath] = useState('');
  const [selectedFile, setSelectedFile] = useState(null);

  // ටීචර්ගේ ටයිම් ටේබල් එකෙන් ශ්‍රේණි ටික ඩයිනමික්ව ගැනීම
  const teacherGrades = Array.isArray(timetable) ? [...new Set(timetable.map(c => c.grade))] : [];
  const [formGrade, setFormGrade] = useState(teacherGrades[0] || 'Grade 10');

  useEffect(() => {
    if (preSelectedGrade) {
      setFormGrade(preSelectedGrade);
      setPreSelectedGrade(null);
    } else if (teacherGrades.length > 0 && !formGrade) {
      setFormGrade(teacherGrades[0]);
    }
  }, [preSelectedGrade, teacherGrades, formGrade, setPreSelectedGrade]);

  const getYoutubeId = (url) => {
    if (!url) return null;
    const regExp = /^.*(youtu.be\/|v\/|u\/\w\/|embed\/|watch\?v=|\&v=)([^#\&\?]*).*/;
    const match = url.match(regExp);
    return (match && match[2].length === 11) ? match[2] : null;
  };

  const handlePublishLesson = (e) => {
    e.preventDefault();
    const formData = new FormData();
    formData.append('title', formTitle);
    formData.append('material_type', formType);
    formData.append('grade', formGrade);
    formData.append('subject', teachingSubject);
    formData.append('teacher_name', userName);

    if ((formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video') && selectedFile) {
        formData.append('file', selectedFile); 
    } else {
        formData.append('file_path', formFilePath);
    }

    axios.post('http://localhost:8082/api/add-material', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
    }).then(res => {
      if (res.data.status === "Success") {
        alert(`✅ ${formType} Published Successfully!`);
        fetchData(); setFormTitle(''); setFormFilePath(''); setSelectedFile(null);
      }
    }).catch(err => console.log(err));
  };

  // 🟢 FIXED PORT: මකන පෝට් එකත් නිවැරදිව 8082 ලෙස සකස් කළා
  const handleDeleteMaterial = (id) => {
    if (window.confirm("Delete this material permanently?")) {
      axios.delete(`http://localhost:8082/api/delete-material/${id}`)
        .then(res => {
          if (res.data.status === "Success") {
            alert("🗑️ Material deleted successfully!");
            fetchData();
          }
        }).catch(err => console.log(err));
    }
  };

  const myMaterials = materials.filter(m => m.subject === teachingSubject);

  return (
    <div style={{ animation: 'fadeIn 0.5s', display: 'flex', flexDirection: 'column', gap: '30px' }}>
      
      {/* Upload Form */}
      <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)' }}>
        <h2 style={{ color: '#1e293b', marginTop: 0, marginBottom: '20px' }}>📤 Content Manager Gateway ({teachingSubject})</h2>
        <form onSubmit={handlePublishLesson} style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
          <input type="text" placeholder="Material Title" value={formTitle} onChange={e => setFormTitle(e.target.value)} required style={styles.input} />
          
          <div style={{ display: 'flex', gap: '20px' }}>
            <select value={formGrade} onChange={e => setFormGrade(e.target.value)} style={{...styles.input, flex: 1}}>
              {teacherGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={formType} onChange={e => { setFormType(e.target.value); setSelectedFile(null); setFormFilePath(''); }} style={{...styles.input, flex: 1}}>
              <option value="PDF">📚 PDF Handout</option>
              <option value="Past Paper">🎯 Past Paper</option>
              <option value="Direct Video">📁 Direct Video (MP4)</option>
              <option value="YouTube">🎬 YouTube Video</option>
              <option value="Zoom Link">🎥 Zoom Live Link</option>
              <option value="Recording">📼 Cloud Recording Link</option>
            </select>
          </div>

          {formType === 'PDF' || formType === 'Past Paper' || formType === 'Direct Video' ? (
            <input type="file" accept={formType === 'Direct Video' ? "video/mp4,video/*" : ".pdf"} onChange={e => setSelectedFile(e.target.files[0])} required style={styles.input} />
          ) : (
            <input type="text" placeholder="Paste URL / Link here..." value={formFilePath} onChange={e => setFormFilePath(e.target.value)} required style={styles.input} />
          )}
          
          <button type="submit" style={styles.btn}>🚀 Publish Material</button>
        </form>
      </div>

      {/* Materials Table with Thumbnails */}
      <div style={{ backgroundColor: 'white', padding: '20px 25px', borderRadius: '15px', boxShadow: '0 4px 15px rgba(0,0,0,0.03)', overflowX: 'auto' }}>
        <h3 style={{ marginTop: 0, marginBottom: '15px' }}>📂 Resource Matrix</h3>
        <table style={{ width: '100%', borderCollapse: 'collapse', textAlign: 'left' }}>
          <thead>
            <tr style={{ borderBottom: '2px solid #f1f5f9', color: '#64748b', fontSize: '13px', height: '40px' }}>
              <th>Preview</th><th>Title</th><th>Grade</th><th>Type</th><th>Access</th><th>Action</th>
            </tr>
          </thead>
          <tbody>
            {myMaterials.length > 0 ? (
              myMaterials.map((m, index) => {
                const ytId = getYoutubeId(m.file_path);
                return (
                  <tr key={m.id || index} style={{ borderBottom: '1px solid #f8fafc', height: '70px', fontSize: '14px' }}>
                    <td>
                      <div style={{ width: '80px', height: '48px', borderRadius: '6px', overflow: 'hidden', backgroundColor: '#f8fafc', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '10px', fontWeight: 'bold' }}>
                        {m.material_type === 'YouTube' && ytId ? (
                          <img src={`https://img.youtube.com/vi/${ytId}/mqdefault.jpg`} alt="Cover" style={{ width: '100%', height: '100%', objectFit: 'cover' }} />
                        ) : <span>{m.material_type}</span>}
                      </div>
                    </td>
                    <td style={{ fontWeight: '600' }}>{m.title}</td>
                    <td>{m.grade}</td>
                    <td>{m.material_type}</td>
                    <td>
                      <a href={m.material_type === 'YouTube' || m.material_type === 'Zoom Link' || m.material_type === 'Recording' ? m.file_path : `http://localhost:8082/${m.file_path}`} target="_blank" rel="noreferrer" style={{ color: '#15803d', fontWeight: 'bold' }}>Open ➔</a>
                    </td>
                    <td>
                      <button onClick={() => handleDeleteMaterial(m.id)} style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: '16px' }}>🗑️</button>
                    </td>
                  </tr>
                );
              })
            ) : (
              <tr><td colSpan="6" style={{ textAlign: 'center', padding: '20px', color: '#94a3b8' }}>No materials uploaded yet.</td></tr>
            )}
          </tbody>
        </table>
      </div>
    </div>
  );
}

const styles = {
  input: { width: '100%', padding: '12px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', boxSizing: 'border-box' },
  btn: { width: '100%', padding: '14px', backgroundColor: '#15803d', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '14px' }
};
